      if (subtitleLow.includes(k)) score += k.length * 1.5;
      for (const t2 of tagsLow) if (t2.includes(k) || k.includes(t2)) score += k.length * 2;
      for (const a of aliasesLow) if (a.includes(k) || k.includes(a)) score += k.length * 2;
