// ../server/src/repos/SqliteStateRepo.ts
var CURRENT_KEY = "center.current";
var SqliteStateRepo = class {
  constructor(db) {
    this.db = db;
  }
  async getCenter() {
    const row = this.db.prepare("SELECT value, updated_at FROM state WHERE key = ?").get(CURRENT_KEY);
    if (!row) return { elementId: null, updatedAt: null };
    return { elementId: row.value || null, updatedAt: row.updated_at };
  }
  async setCenter(elementId) {
    const prior = await this.getCenter();
    const ts2 = (/* @__PURE__ */ new Date()).toISOString();
    const dwellMs = prior.updatedAt ? new Date(ts2).getTime() - new Date(prior.updatedAt).getTime() : null;
    const change = { ts: ts2, from: prior.elementId, to: elementId, dwellMs };
    const tx = this.db.transaction(() => {
      this.db.prepare(`
        INSERT INTO state (key, value, updated_at) VALUES (?, ?, ?)
        ON CONFLICT(key) DO UPDATE SET value=excluded.value, updated_at=excluded.updated_at
      `).run(CURRENT_KEY, elementId, ts2);
      this.db.prepare(`
        INSERT INTO center_history (ts, from_id, to_id, dwell_ms) VALUES (?, ?, ?, ?)
      `).run(ts2, prior.elementId, elementId, dwellMs);
    });
    tx();
    return change;
  }
  async recentChanges(limit = 20) {
    const rows = this.db.prepare(
      "SELECT ts, from_id, to_id, dwell_ms FROM center_history ORDER BY id DESC LIMIT ?"
    ).all(limit);
    return rows.map((r) => ({ ts: r.ts, from: r.from_id, to: r.to_id, dwellMs: r.dwell_ms }));
  }
};

// ../server/src/repos/SqliteCorpusRepo.ts
var KEY = "ai.corpus.templates.v1";
var SqliteCorpusRepo = class {
  constructor(db) {
    this.db = db;
  }
  async getAll() {
    const row = this.db.prepare("SELECT value FROM state WHERE key = ?").get(KEY);
    if (!row) return null;
    try {
      return normalizeCorpusTemplates(JSON.parse(row.value));
    } catch {
      return null;
    }
  }
  async putAll(templates) {
    const ts2 = (/* @__PURE__ */ new Date()).toISOString();
    this.db.prepare(`
      INSERT INTO state (key, value, updated_at) VALUES (?, ?, ?)
      ON CONFLICT(key) DO UPDATE SET value=excluded.value, updated_at=excluded.updated_at
    `).run(KEY, JSON.stringify(templates), ts2);
  }
};

