var MAX_BODY_BYTES = 256 * 1024;
function greatMeRoutes(repo) {
  const r = new Hono2();
  r.get("/state", async (c) => {
    const raw2 = await repo.get();
    if (raw2 == null) return c.json({ state: null });
    const parsed = GreatMeStateSchema.safeParse(raw2);
    if (!parsed.success) {
      return c.json({ state: null, warning: "stored state failed schema; ignored" });
    }
    return c.json({ state: parsed.data });
  });
  r.put("/state", async (c) => {
    const text2 = await c.req.text();
    if (text2.length > MAX_BODY_BYTES) {
      return c.json({ error: `state too large (>${MAX_BODY_BYTES} bytes)` }, 413);
    }
    let body;
    try {
      body = JSON.parse(text2);
    } catch {
      return c.json({ error: "invalid JSON" }, 400);
    }
    const parsed = GreatMeStateSchema.safeParse(body);
    if (!parsed.success) {
      return c.json({ error: "schema validation failed", issues: parsed.error.issues }, 400);
    }
    const stored = await repo.get();
    const storedParsed = stored == null ? null : GreatMeStateSchema.safeParse(stored);
    const currentVersion = storedParsed && storedParsed.success ? storedParsed.data.version : 0;
    if (parsed.data.version !== currentVersion) {
      return c.json({
        error: "version conflict",
        current: storedParsed && storedParsed.success ? storedParsed.data : null,
        currentVersion
      }, 409);
    }
    const next = { ...parsed.data, version: currentVersion + 1 };
    await repo.put(next);
    return c.json({ ok: true, version: next.version });
  });
  return r;
}

